// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";

/// @title GolfToken (GOLF) — prêmio e taxa do CU Golf
/// @notice ERC-20 padrão (OpenZeppelin). Só o `minter` (o contrato SbpfGolf) pode emitir, até
///         MAX_SUPPLY. Queimas acontecem via `burnFrom`/`burn` do ERC20Burnable.
///         Sem funções de admin além de definir o minter uma única vez.
contract GolfToken is ERC20, ERC20Burnable {
    uint256 public constant MAX_SUPPLY = 21_000_000 ether;

    address public minter;
    address public immutable deployer;

    error NotMinter();
    error MinterAlreadySet();
    error MaxSupplyExceeded();

    constructor() ERC20("CU Golf", "GOLF") {
        deployer = msg.sender;
    }

    /// @notice Define o minter uma única vez (chamado pelo deployer logo após o deploy do SbpfGolf).
    function setMinter(address minter_) external {
        if (msg.sender != deployer || minter != address(0)) revert MinterAlreadySet();
        minter = minter_;
    }

    function mint(address to, uint256 amount) external {
        if (msg.sender != minter) revert NotMinter();
        if (totalSupply() + amount > MAX_SUPPLY) revert MaxSupplyExceeded();
        _mint(to, amount);
    }
}

contracts/src/SbpfGolf.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {SbpfVM} from "./SbpfVM.sol";
import {Tasks} from "./Tasks.sol";
import {GolfToken} from "./GolfToken.sol";
import {BlockSeed} from "./BlockSeed.sol";

interface IBountyBoard {
    function referenceSpec(uint256 id) external view returns (bool active, bytes memory program, uint64 maxCu, uint32 inputLen);
}

/// @title SbpfGolf — "CU Golf": mint exige rodar programas Solana dentro do contrato
/// @notice Rodadas de commit-reveal. A tarefa da rodada é conhecida antes do commit. Cada jogador
///         comita o hash do seu programa sBPF (e paga a taxa de entrada em GOLF); depois revela o
///         programa, que é verificado e executado pelo SbpfVM em K inputs derivados de uma seed
///         (hash do último bloco de commit, desconhecida na hora do commit; via EIP-2935 quando
///         já passou de 256 blocos). Ganha quem gastar
///         menos compute units com todas as respostas certas. Empate: commit mais antigo.
///
///         Seção 6.1 (taxa de entrada): parte queimada, resto vai para o prêmio da rodada.
///         Seção 6.3 (leilão da próxima tarefa): a maior oferta em GOLF escolhe a tarefa seguinte
///         (uma da lista ou um bounty ativo do BountyBoard); a oferta vencedora é queimada e as
///         perdedoras são devolvidas (pull: `claimRefund`).
///
/// @dev Tarefas: 0..NUM_TASKS-1 são as nativas (Tasks.sol); BOUNTY_TASK_BASE + id usa o programa
///      de referência do bounty como oráculo de correção.
contract SbpfGolf {
    // ------------------------------------------------------------------ parâmetros
    uint256 public constant K_INPUTS = 4;
    uint64 public constant MAX_CU_PER_INPUT = 5_000;
    uint256 public constant MAX_PROGRAM_BYTES = 256 * 8;
    uint256 public constant BOUNTY_TASK_BASE = 1_000;

    uint256 public constant BASE_REWARD = 100 ether;
    uint256 public constant HALVING_ROUNDS = 1_000;

    uint256 public immutable ENTRY_FEE;
    uint256 public immutable ENTRY_BURN_BPS; // parte da taxa queimada (resto vai para o prêmio)
    uint256 public immutable FREE_ROUNDS; // rodadas iniciais sem taxa (ninguém tem GOLF antes do 1º mint)
    uint64 public immutable COMMIT_BLOCKS;
    uint64 public immutable REVEAL_BLOCKS;

    SbpfVM public immutable vm;
    GolfToken public immutable token;
    IBountyBoard public bountyBoard; // definido uma vez pelo deployer

    // ------------------------------------------------------------------ estado
    struct Round {
        uint256 task;
        uint64 commitEnd; // último bloco em que se pode comitar
        uint64 revealEnd; // último bloco em que se pode revelar
        bytes32 seed; // hash do bloco commitEnd, gravada no primeiro reveal
        address best;
        uint64 bestCu;
        uint64 bestCommitBlock;
        uint256 prize; // taxas de entrada acumuladas (GOLF) desta rodada
        bool finalized;
        // leilão da próxima tarefa
        address topBidder;
        uint256 topBid;
        uint256 topChoice;
    }

    struct Commit {
        bytes32 hash;
        uint64 blockNumber;
        bool revealed;
    }

    struct Bid {
        uint256 choice;
        uint256 amount;
        bool refunded;
    }

    uint256 public round;
    uint256 public carry; // prêmio não distribuído (sem vencedor) que passa para a rodada seguinte
    address public immutable deployer;
    mapping(uint256 => Round) public rounds;
    mapping(uint256 => mapping(address => Commit)) public commits;
    mapping(uint256 => mapping(address => Bid)) public bids;

    // ------------------------------------------------------------------ eventos / erros
    event RoundStarted(uint256 indexed round, uint256 task, uint64 commitEnd, uint64 revealEnd);
    event Committed(uint256 indexed round, address indexed player, bytes32 hash);
    event Revealed(uint256 indexed round, address indexed player, uint64 totalCu, bool isBest, bytes program);
    event Finalized(uint256 indexed round, address indexed winner, uint64 cu, uint256 reward, uint256 prize);
    event BidPlaced(uint256 indexed round, address indexed bidder, uint256 choice, uint256 total);
    event BidRefunded(uint256 indexed round, address indexed bidder, uint256 amount);

    error NotCommitWindow();
    error NotRevealWindow();
    error RoundNotOver();
    error AlreadyFinalized();
    error AlreadyCommitted();
    error AlreadyRevealed();
    error NoCommit();
    error BadReveal();
    error ProgramTooLarge();
    error ProgramRejected(uint256 inputIndex, SbpfVM.Status status, uint64 r0, uint64 expected);
    error BidTooLow(uint256 topBid);
    error InvalidChoice();
    error NothingToRefund();
    error NotDeployer();
    error RevealWindowTooLong();
    error SeedUnavailable();

    constructor(
        SbpfVM vm_,
        GolfToken token_,
        uint256 entryFee_,
        uint256 entryBurnBps,
        uint256 freeRounds,
        uint64 commitBlocks,
        uint64 revealBlocks
    ) {
        if (revealBlocks == 0 || revealBlocks > BlockSeed.MAX_REVEAL_BLOCKS || commitBlocks == 0 || entryBurnBps > 10_000) revert RevealWindowTooLong();
        vm = vm_;
        token = token_;
        ENTRY_FEE = entryFee_;
        ENTRY_BURN_BPS = entryBurnBps;
        FREE_ROUNDS = freeRounds;
        COMMIT_BLOCKS = commitBlocks;
        REVEAL_BLOCKS = revealBlocks;
        deployer = msg.sender;
        _startRound(1, 1 % Tasks.NUM_TASKS);
    }

    function setBountyBoard(IBountyBoard board) external {
        if (msg.sender != deployer || address(bountyBoard) != address(0)) revert NotDeployer();
        bountyBoard = board;
    }

    // ------------------------------------------------------------------ jogo

    /// @notice Hash que o jogador deve comitar.
    function commitHash(address player, uint256 round_, bytes calldata program, bytes32 salt) external pure returns (bytes32) {
        return keccak256(abi.encode(player, round_, keccak256(program), salt));
    }

    /// @notice Comita `keccak256(abi.encode(msg.sender, round, keccak256(program), salt))` e paga a taxa.
    function commit(bytes32 hash) external {
        Round storage r = rounds[round];
        if (block.number > r.commitEnd) revert NotCommitWindow();
        Commit storage c = commits[round][msg.sender];
        if (c.hash != bytes32(0)) revert AlreadyCommitted();
        c.hash = hash;
        c.blockNumber = uint64(block.number);

        uint256 fee = entryFee();
        if (fee > 0) {
            uint256 burn = (fee * ENTRY_BURN_BPS) / 10_000;
            if (burn > 0) token.burnFrom(msg.sender, burn);
            uint256 toPrize = fee - burn;
            if (toPrize > 0) {
                token.transferFrom(msg.sender, address(this), toPrize);
                r.prize += toPrize;
            }
        }
        emit Committed(round, msg.sender, hash);
    }

    /// @notice Revela o programa. Executa em K inputs; reverte se alguma resposta estiver errada.
    /// @return totalCu compute units somadas nos K inputs
    function reveal(bytes calldata program, bytes32 salt) external returns (uint64 totalCu) {
        Round storage r = rounds[round];
        if (block.number <= r.commitEnd || block.number > r.revealEnd) revert NotRevealWindow();
        Commit storage c = commits[round][msg.sender];
        if (c.hash == bytes32(0)) revert NoCommit();
        if (c.revealed) revert AlreadyRevealed();
        if (keccak256(abi.encode(msg.sender, round, keccak256(program), salt)) != c.hash) revert BadReveal();
        if (program.length > MAX_PROGRAM_BYTES) revert ProgramTooLarge();
        c.revealed = true;

        if (r.seed == bytes32(0)) {
            // ninguém conhecia este hash durante a janela de commit
            r.seed = BlockSeed.hashOf(r.commitEnd);
            if (r.seed == bytes32(0)) revert SeedUnavailable();
        }

        totalCu = judge(r.task, r.seed, program);

        bool isBest = r.best == address(0) || totalCu < r.bestCu
            || (totalCu == r.bestCu && c.blockNumber < r.bestCommitBlock);
        if (isBest) {
            r.best = msg.sender;
            r.bestCu = totalCu;
            r.bestCommitBlock = c.blockNumber;
        }
        emit Revealed(round, msg.sender, totalCu, isBest, program);
    }

    /// @notice Executa `program` nos K inputs da tarefa e devolve a soma de CU. Reverte com
    ///         `ProgramRejected` se alguma execução falhar ou responder errado.
    function judge(uint256 task, bytes32 seed, bytes calldata program) public view returns (uint64 totalCu) {
        bool isBounty = task >= BOUNTY_TASK_BASE;
        bytes memory refProgram;
        uint64 refMaxCu;
        uint32 inputLen;
        if (isBounty) {
            bool active;
            (active, refProgram, refMaxCu, inputLen) = bountyBoard.referenceSpec(task - BOUNTY_TASK_BASE);
            if (!active) revert InvalidChoice();
        }

        uint256 used;
        for (uint256 k = 0; k < K_INPUTS; k++) {
            bytes memory input;
            uint64 want;
            if (isBounty) {
                input = _randomBytes(seed, k, inputLen);
                (SbpfVM.Status rs, uint64 rr0,) = vm.run(refProgram, input, refMaxCu);
                if (rs != SbpfVM.Status.Ok) continue; // input em que a referência falha é descartado
                want = rr0;
            } else {
                input = Tasks.inputFor(task, seed, k);
                want = Tasks.expected(task, input);
            }
            (SbpfVM.Status status, uint64 r0, uint64 cu) = vm.run(program, input, MAX_CU_PER_INPUT);
            if (status != SbpfVM.Status.Ok || r0 != want) revert ProgramRejected(k, status, r0, want);
            totalCu += cu;
            used++;
        }
        if (used == 0) revert ProgramRejected(type(uint256).max, SbpfVM.Status.Invalid, 0, 0);
    }

    /// @notice Encerra a rodada (qualquer um pode chamar depois da janela de reveal) e abre a próxima.
    function finalize() external {
        Round storage r = rounds[round];
        if (block.number <= r.revealEnd) revert RoundNotOver();
        if (r.finalized) revert AlreadyFinalized();
        r.finalized = true;

        uint256 reward = currentReward();
        uint256 prize = r.prize + carry;
        if (r.best != address(0)) {
            carry = 0;
            if (reward > 0) token.mint(r.best, reward);
            if (prize > 0) token.transfer(r.best, prize);
            emit Finalized(round, r.best, r.bestCu, reward, prize);
        } else {
            carry = prize;
            emit Finalized(round, address(0), 0, 0, 0);
        }

        // leilão: a oferta vencedora é queimada; as outras ficam disponíveis em claimRefund
        uint256 nextTask = (round + 1) % Tasks.NUM_TASKS;
        if (r.topBidder != address(0)) {
            token.burn(r.topBid);
            nextTask = r.topChoice;
            bids[round][r.topBidder].refunded = true; // nada a devolver
        }
        _startRound(round + 1, nextTask);
    }

    /// @notice Taxa de entrada da rodada atual (zero nas FREE_ROUNDS primeiras rodadas).
    function entryFee() public view returns (uint256) {
        return round <= FREE_ROUNDS ? 0 : ENTRY_FEE;
    }

    /// @notice Recompensa em GOLF da rodada atual (halving a cada HALVING_ROUNDS, limitado ao supply).
    function currentReward() public view returns (uint256 reward) {
        uint256 halvings = (round - 1) / HALVING_ROUNDS;
        reward = halvings >= 64 ? 0 : BASE_REWARD >> halvings;
        uint256 left = token.MAX_SUPPLY() - token.totalSupply();
        if (reward > left) reward = left;
    }

    // ------------------------------------------------------------------ leilão da próxima tarefa (6.3)

    /// @notice Oferece GOLF para escolher a tarefa da próxima rodada. Ofertas do mesmo endereço se
    ///         acumulam; o total precisa superar a maior oferta atual.
    /// @param choice id de tarefa nativa (0..NUM_TASKS-1) ou BOUNTY_TASK_BASE + id de bounty ativo
    function bid(uint256 choice, uint256 amount) external {
        Round storage r = rounds[round];
        if (block.number > r.revealEnd) revert RoundNotOver();
        if (!_validChoice(choice)) revert InvalidChoice();
        Bid storage b = bids[round][msg.sender];
        if (b.amount != 0 && b.choice != choice) revert InvalidChoice();
        token.transferFrom(msg.sender, address(this), amount);
        b.choice = choice;
        b.amount += amount;
        if (b.amount <= r.topBid) revert BidTooLow(r.topBid);
        r.topBid = b.amount;
        r.topBidder = msg.sender;
        r.topChoice = choice;
        emit BidPlaced(round, msg.sender, choice, b.amount);
    }

    /// @notice Devolve a oferta perdedora de uma rodada já finalizada.
    function claimRefund(uint256 round_) external {
        Round storage r = rounds[round_];
        Bid storage b = bids[round_][msg.sender];
        if (!r.finalized || b.amount == 0 || b.refunded) revert NothingToRefund();
        b.refunded = true;
        token.transfer(msg.sender, b.amount);
        emit BidRefunded(round_, msg.sender, b.amount);
    }

    // ------------------------------------------------------------------ leitura

    function currentRound() external view returns (Round memory) {
        return rounds[round];
    }

    function taskName(uint256 task) external pure returns (string memory) {
        return task >= BOUNTY_TASK_BASE ? "bounty" : Tasks.name(task);
    }

    /// @notice Inputs que serão usados no reveal (só conhecidos depois da seed).
    function inputsFor(uint256 round_) external view returns (bytes[] memory inputs) {
        Round storage r = rounds[round_];
        inputs = new bytes[](K_INPUTS);
        if (r.task >= BOUNTY_TASK_BASE) {
            (, , , uint32 inputLen) = bountyBoard.referenceSpec(r.task - BOUNTY_TASK_BASE);
            for (uint256 k = 0; k < K_INPUTS; k++) inputs[k] = _randomBytes(r.seed, k, inputLen);
        } else {
            for (uint256 k = 0; k < K_INPUTS; k++) inputs[k] = Tasks.inputFor(r.task, r.seed, k);
        }
    }

    // ------------------------------------------------------------------ internos

    function _startRound(uint256 n, uint256 task) internal {
        Round storage r = rounds[n];
        round = n;
        r.task = task;
        r.commitEnd = uint64(block.number) + COMMIT_BLOCKS;
        r.revealEnd = r.commitEnd + REVEAL_BLOCKS;
        emit RoundStarted(n, task, r.commitEnd, r.revealEnd);
    }

    function _validChoice(uint256 choice) internal view returns (bool) {
        if (choice < Tasks.NUM_TASKS) return true;
        if (choice < BOUNTY_TASK_BASE || address(bountyBoard) == address(0)) return false;
        (bool active,,,) = bountyBoard.referenceSpec(choice - BOUNTY_TASK_BASE);
        return active;
    }

    function _randomBytes(bytes32 seed, uint256 k, uint256 len) internal pure returns (bytes memory out) {
        out = new bytes(len);
        for (uint256 i = 0; i < len; i += 32) {
            bytes32 h = keccak256(abi.encode(seed, k, i));
            for (uint256 j = 0; j < 32 && i + j < len; j++) out[i + j] = h[j];
        }
    }
}

contracts/src/SbpfVM.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title SbpfVM — interpretador sBPF v0 (formato legado dos programas Solana) em Solidity
/// @notice Executa um programa sBPF instrução por instrução dentro da EVM. A semântica segue o
///         crate `solana-sbpf` 0.26.0 (`interpreter.rs` e `verifier.rs`, SBPFVersion::V0) e é
///         conferida pelos fixtures em `fixtures/`, gerados pela VM oficial.
///
///         Subconjunto suportado: ALU64, ALU32, JMP (64 bits), LDX, ST, STX, lddw, exit.
///         Fora do subconjunto: call/callx, syscalls, heap, rodata, ELF, accounts, CPI.
///         `call`/`callx` passam no verificador (como na referência) e falham na execução com
///         `Invalid`, que é o que a referência também devolve (UnsupportedInstruction /
///         CallDepthExceeded com max_call_depth = 1).
///
/// @dev Mapa de memória:
///         0x2_0000_0000  pilha, 4 KiB, leitura/escrita (um único frame; r10 aponta para o topo)
///         0x4_0000_0000  input, somente leitura
///      Registradores: r0..r9 de uso geral, r10 = frame pointer (somente leitura).
///      Compute units: 1 por instrução executada (lddw conta 1).
contract SbpfVM {
    enum Status {
        Ok,
        Invalid,
        DivideByZero,
        AccessViolation,
        CuExceeded
    }

    uint64 public constant STACK_START = 0x200000000;
    uint64 public constant STACK_SIZE = 4096;
    uint64 public constant INPUT_START = 0x400000000;

    /// @notice Verifica e executa um programa. Nunca reverte por erro do programa: devolve o status.
    /// @param program bytecode sBPF (múltiplo de 8 bytes)
    /// @param input   bytes mapeados em INPUT_START (r1 aponta para eles)
    /// @param maxCu   limite de compute units (instruções)
    /// @return status resultado da execução
    /// @return r0     valor de retorno (0 quando status != Ok)
    /// @return cuUsed compute units consumidas (inclui a instrução que falhou)
    function run(bytes calldata program, bytes calldata input, uint64 maxCu)
        external
        pure
        returns (Status status, uint64 r0, uint64 cuUsed)
    {
        if (!verify(program)) return (Status.Invalid, 0, 0);
        return execute(program, input, maxCu);
    }

    // ------------------------------------------------------------------ verificador

    /// @notice Verificador estático, equivalente ao `RequisiteVerifier` do solana-sbpf para V0.
    function verify(bytes calldata program) public pure returns (bool) {
        uint256 len = program.length;
        if (len == 0 || len % 8 != 0) return false;
        uint256 n = len / 8;
        uint256 base = 0;
        assembly {
            base := program.offset
        }

        unchecked {
            for (uint256 i = 0; i < n; i++) {
                uint256 opc;
                uint256 dst;
                uint256 src;
                int256 off;
                int256 imm;
                assembly {
                    let w := calldataload(add(base, mul(i, 8)))
                    opc := byte(0, w)
                    dst := and(byte(1, w), 0x0f)
                    src := shr(4, byte(1, w))
                    off := signextend(1, or(byte(2, w), shl(8, byte(3, w))))
                    imm := signextend(3, or(or(byte(4, w), shl(8, byte(5, w))), or(shl(16, byte(6, w)), shl(24, byte(7, w)))))
                }
                uint256 cls = opc & 7;
                uint256 op = opc & 0xf0;
                bool isReg = (opc & 8) != 0;
                bool store = false;

                if (cls == 7 || cls == 4) {
                    // ALU64 / ALU32
                    if (op == 0xd0) {
                        // le (0xd4) / be (0xdc): só ALU32, imm ∈ {16, 32, 64}
                        if (cls != 4) return false;
                        if (imm != 16 && imm != 32 && imm != 64) return false;
                    } else if (op > 0xc0) {
                        return false;
                    } else if (op == 0x80) {
                        // neg: só a forma sem registrador (0x84 / 0x87)
                        if (isReg) return false;
                    } else if (!isReg) {
                        if ((op == 0x30 || op == 0x90) && imm == 0) return false; // div/mod por imediato 0
                        if (op == 0x60 || op == 0x70 || op == 0xc0) {
                            // shift por imediato: 0 <= imm < bits
                            if (imm < 0 || imm >= (cls == 7 ? int256(64) : int256(32))) return false;
                        }
                    }
                } else if (cls == 5) {
                    // JMP
                    if (op == 0x00) {
                        if (isReg) return false; // ja = 0x05
                        if (!_jumpOk(base, n, i, off)) return false;
                    } else if (op == 0x80) {
                        // 0x85 call (resolvido em execução), 0x8d callx (imm = registrador alvo)
                        if (isReg && (imm < 0 || imm >= 10)) return false;
                    } else if (op == 0x90) {
                        if (isReg) return false; // exit = 0x95
                    } else if (op > 0xd0) {
                        return false;
                    } else {
                        if (!_jumpOk(base, n, i, off)) return false;
                    }
                } else if (cls == 1) {
                    if ((opc & 0xe7) != 0x61) return false; // ldx{w,h,b,dw}
                } else if (cls == 2) {
                    if ((opc & 0xe7) != 0x62) return false; // st{w,h,b,dw}
                    store = true;
                } else if (cls == 3) {
                    if ((opc & 0xe7) != 0x63) return false; // stx{w,h,b,dw}
                    store = true;
                } else if (opc == 0x18) {
                    // lddw: não pode ser a última instrução e o slot seguinte precisa ter opcode 0
                    if (i + 1 >= n) return false;
                    uint256 nextOpc;
                    assembly {
                        nextOpc := byte(0, calldataload(add(base, mul(add(i, 1), 8))))
                    }
                    if (nextOpc != 0) return false;
                    i++;
                } else {
                    return false;
                }

                // registradores: src <= 10; dst <= 9, ou dst == 10 apenas em stores
                if (src > 10) return false;
                if (dst > 10 || (dst == 10 && !store)) return false;
            }
        }
        return true;
    }

    function _jumpOk(uint256 base, uint256 n, uint256 i, int256 off) private pure returns (bool) {
        unchecked {
            int256 t = int256(i) + 1 + off;
            if (t < 0 || t >= int256(n)) return false;
            uint256 targetOpc;
            assembly {
                targetOpc := byte(0, calldataload(add(base, mul(t, 8))))
            }
            return targetOpc != 0; // não pode pular para o meio de um lddw
        }
    }

    // ------------------------------------------------------------------ interpretador

    /// @notice Executa um programa já verificado. Chamar sem `verify` em bytecode arbitrário não é
    ///         seguro para a equivalência com a referência (opcodes desconhecidos são tratados
    ///         como `Invalid`, mas registradores fora de r0..r10 não são checados).
    function execute(bytes calldata program, bytes calldata input, uint64 maxCu)
        public
        pure
        returns (Status status, uint64 r0, uint64 cuUsed)
    {
        uint256 codeOff;
        uint256 inPacked;
        assembly {
            codeOff := program.offset
            inPacked := or(shl(128, input.offset), input.length)
        }
        (uint256 st, uint256 ret, uint256 cu) = _exec(codeOff, program.length / 8, inPacked, maxCu);
        status = Status(st);
        r0 = uint64(ret);
        cuUsed = uint64(cu);
    }

    /// @dev Loop principal em Yul. Poucas variáveis locais de propósito (limite da pilha da EVM).
    ///      `inPacked` = (offset do input em calldata) << 128 | (tamanho do input).
    function _exec(uint256 codeOff, uint256 n, uint256 inPacked, uint256 maxCu)
        private
        pure
        returns (uint256 st, uint256 ret, uint256 cu)
    {
        assembly ("memory-safe") {
            // --- memória da VM: 11 palavras de registradores seguidas de 4096 bytes de pilha
            let regs := mload(0x40)
            mstore(0x40, add(regs, 4448))
            for { let p := regs } lt(p, add(regs, 4448)) { p := add(p, 32) } { mstore(p, 0) }
            mstore(add(regs, 32), 0x400000000) // r1 = input
            mstore(add(regs, 320), 0x200001000) // r10 = topo da pilha (STACK_START + STACK_SIZE)

            // lê `size` bytes little-endian a partir dos bytes mais altos da palavra w
            function le(w, size) -> v {
                for { let i := 0 } lt(i, size) { i := add(i, 1) } { v := or(v, shl(mul(i, 8), byte(i, w))) }
            }
            // traduz um endereço virtual para leitura; devolve (ok, palavra lida)
            function load(vaddr, size, regs_, inp) -> ok, w {
                let s := sub(vaddr, 0x200000000)
                if lt(s, 4096) {
                    if iszero(gt(add(s, size), 4096)) {
                        ok := 1
                        w := mload(add(add(regs_, 352), s))
                    }
                    leave
                }
                let q := sub(vaddr, 0x400000000)
                let inlen := and(inp, 0xffffffffffffffffffffffffffffffff)
                if lt(q, inlen) {
                    if iszero(gt(add(q, size), inlen)) {
                        ok := 1
                        w := calldataload(add(shr(128, inp), q))
                    }
                }
            }
            // escreve `size` bytes little-endian na pilha (única região gravável)
            function store(vaddr, size, value, regs_) -> ok {
                let s := sub(vaddr, 0x200000000)
                if lt(s, 4096) {
                    if iszero(gt(add(s, size), 4096)) {
                        ok := 1
                        let p := add(add(regs_, 352), s)
                        for { let i := 0 } lt(i, size) { i := add(i, 1) } {
                            mstore8(add(p, i), byte(sub(31, i), value))
                        }
                    }
                }
            }
            function bswap(v, nbytes) -> out {
                for { let i := 0 } lt(i, nbytes) { i := add(i, 1) } {
                    out := or(shl(8, out), and(shr(mul(8, i), v), 0xff))
                }
            }
            function offset(w) -> o {
                o := signextend(1, or(byte(2, w), shl(8, byte(3, w))))
            }
            function memsize(opc) -> size {
                size := 4
                switch and(opc, 0x18)
                case 0x08 { size := 2 }
                case 0x10 { size := 1 }
                case 0x18 { size := 8 }
            }

            let ip := 0
            for {} 1 {} {
                // medidor de instruções: igual à referência, checa antes de executar
                if iszero(lt(cu, maxCu)) {
                    st := 4
                    break
                }
                cu := add(cu, 1)
                if iszero(lt(ip, n)) {
                    st := 1 // ExecutionOverrun
                    break
                }
                let w := calldataload(add(codeOff, shl(3, ip)))
                let opc := byte(0, w)
                let dstp := add(regs, shl(5, and(byte(1, w), 0x0f)))
                let imm := or(or(byte(4, w), shl(8, byte(5, w))), or(shl(16, byte(6, w)), shl(24, byte(7, w))))
                ip := add(ip, 1)

                switch and(opc, 7)
                case 7 {
                    // ---------------- ALU64 (imediato estendido com sinal)
                    let a := mload(dstp)
                    let b := and(signextend(3, imm), 0xffffffffffffffff)
                    if and(opc, 8) { b := mload(add(regs, shl(5, shr(4, byte(1, w))))) }
                    switch and(opc, 0xf0)
                    case 0x00 { a := and(add(a, b), 0xffffffffffffffff) }
                    case 0x10 { a := and(sub(a, b), 0xffffffffffffffff) }
                    case 0x20 { a := and(mul(a, b), 0xffffffffffffffff) }
                    case 0x30 {
                        if iszero(b) {
                            st := 2
                            break
                        }
                        a := div(a, b)
                    }
                    case 0x40 { a := or(a, b) }
                    case 0x50 { a := and(a, b) }
                    case 0x60 { a := and(shl(and(b, 63), a), 0xffffffffffffffff) }
                    case 0x70 { a := shr(and(b, 63), a) }
                    case 0x80 { a := and(sub(0, a), 0xffffffffffffffff) }
                    case 0x90 {
                        if iszero(b) {
                            st := 2
                            break
                        }
                        a := mod(a, b)
                    }
                    case 0xa0 { a := xor(a, b) }
                    case 0xb0 { a := b }
                    case 0xc0 { a := and(sar(and(b, 63), signextend(7, a)), 0xffffffffffffffff) }
                    default {
                        st := 1
                        break
                    }
                    mstore(dstp, a)
                }
                case 4 {
                    // ---------------- ALU32
                    let a := and(mload(dstp), 0xffffffff)
                    let b := imm
                    if and(opc, 8) { b := and(mload(add(regs, shl(5, shr(4, byte(1, w))))), 0xffffffff) }
                    switch and(opc, 0xf0)
                    // add/sub/mul: resultado i32 estendido com sinal para 64 bits (sBPF v0)
                    case 0x00 { a := and(signextend(3, add(a, b)), 0xffffffffffffffff) }
                    case 0x10 { a := and(signextend(3, sub(a, b)), 0xffffffffffffffff) }
                    case 0x20 { a := and(signextend(3, mul(a, b)), 0xffffffffffffffff) }
                    case 0x30 {
                        if iszero(b) {
                            st := 2
                            break
                        }
                        a := div(a, b)
                    }
                    case 0x40 { a := or(a, b) }
                    case 0x50 { a := and(a, b) }
                    case 0x60 { a := and(shl(and(b, 31), a), 0xffffffff) }
                    case 0x70 { a := shr(and(b, 31), a) }
                    case 0x80 { a := and(sub(0, a), 0xffffffff) }
                    case 0x90 {
                        if iszero(b) {
                            st := 2
                            break
                        }
                        a := mod(a, b)
                    }
                    case 0xa0 { a := xor(a, b) }
                    case 0xb0 { a := b }
                    case 0xc0 { a := and(sar(and(b, 31), signextend(3, a)), 0xffffffff) }
                    case 0xd0 {
                        // le (0xd4): só trunca; be (0xdc): inverte os bytes
                        a := mload(dstp)
                        switch imm
                        case 16 { a := and(a, 0xffff) }
                        case 32 { a := and(a, 0xffffffff) }
                        if and(opc, 8) { a := bswap(a, shr(3, imm)) }
                    }
                    default {
                        st := 1
                        break
                    }
                    mstore(dstp, a)
                }
                case 5 {
                    // ---------------- JMP / exit / call
                    switch opc
                    case 0x05 { ip := add(ip, offset(w)) }
                    case 0x95 {
                        ret := mload(regs)
                        break
                    }
                    default {
                        if eq(and(opc, 0xf0), 0x80) {
                            // call / callx: fora do subconjunto (sem syscalls, sem frames)
                            st := 1
                            break
                        }
                        let a := mload(dstp)
                        let b := and(signextend(3, imm), 0xffffffffffffffff)
                        if and(opc, 8) { b := mload(add(regs, shl(5, shr(4, byte(1, w))))) }
                        switch and(opc, 0xf0)
                        case 0x10 { a := eq(a, b) }
                        case 0x20 { a := gt(a, b) }
                        case 0x30 { a := iszero(lt(a, b)) }
                        case 0x40 { a := iszero(iszero(and(a, b))) }
                        case 0x50 { a := iszero(eq(a, b)) }
                        case 0x60 { a := sgt(signextend(7, a), signextend(7, b)) }
                        case 0x70 { a := iszero(slt(signextend(7, a), signextend(7, b))) }
                        case 0xa0 { a := lt(a, b) }
                        case 0xb0 { a := iszero(gt(a, b)) }
                        case 0xc0 { a := slt(signextend(7, a), signextend(7, b)) }
                        case 0xd0 { a := iszero(sgt(signextend(7, a), signextend(7, b))) }
                        default {
                            st := 1
                            break
                        }
                        if a { ip := add(ip, offset(w)) }
                    }
                }
                case 1 {
                    // ---------------- LDX: dst = *(size*)(src + off)
                    let a := mload(add(regs, shl(5, shr(4, byte(1, w)))))
                    let ok, mw := load(and(add(a, offset(w)), 0xffffffffffffffff), memsize(opc), regs, inPacked)
                    if iszero(ok) {
                        st := 3
                        break
                    }
                    mstore(dstp, le(mw, memsize(opc)))
                }
                case 2 {
                    // ---------------- ST: *(size*)(dst + off) = imm (estendido com sinal)
                    if iszero(store(and(add(mload(dstp), offset(w)), 0xffffffffffffffff), memsize(opc), signextend(3, imm), regs)) {
                        st := 3
                        break
                    }
                }
                case 3 {
                    // ---------------- STX: *(size*)(dst + off) = src
                    let a := mload(add(regs, shl(5, shr(4, byte(1, w)))))
                    if iszero(store(and(add(mload(dstp), offset(w)), 0xffffffffffffffff), memsize(opc), a, regs)) {
                        st := 3
                        break
                    }
                }
                default {
                    // ---------------- lddw (0x18): 16 bytes, imm64 = imm | imm2 << 32
                    if iszero(eq(opc, 0x18)) {
                        st := 1
                        break
                    }
                    w := calldataload(add(codeOff, shl(3, ip)))
                    mstore(dstp, or(imm, shl(32, or(or(byte(4, w), shl(8, byte(5, w))), or(shl(16, byte(6, w)), shl(24, byte(7, w)))))))
                    ip := add(ip, 1)
                }
            }
            if st { ret := 0 }
        }
    }
}

contracts/src/Tasks.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @title Tasks — tarefas do CU Golf com implementação nativa em Solidity
/// @notice Cada tarefa tem (a) um gerador de inputs a partir de uma seed e (b) a resposta esperada,
///         calculada com a mesma aritmética de 64 bits com wraparound da VM. O programa sBPF do
///         jogador recebe o input em r1 (região INPUT) e devolve a resposta em r0.
library Tasks {
    uint256 internal constant NUM_TASKS = 5;

    uint256 internal constant FIB = 0; // [u64 n]      -> fib(n) mod 2^64
    uint256 internal constant POPCOUNT = 1; // [u64 x]      -> bits 1 em x
    uint256 internal constant ISQRT = 2; // [u64 x]      -> floor(sqrt(x))
    uint256 internal constant MAX8 = 3; // [u64 x 8]    -> máximo sem sinal
    uint256 internal constant GCD = 4; // [u64 a][u64 b] -> mdc(a, b), mdc(a, 0) = a

    function name(uint256 task) internal pure returns (string memory) {
        if (task == FIB) return "fib";
        if (task == POPCOUNT) return "popcount";
        if (task == ISQRT) return "isqrt";
        if (task == MAX8) return "max8";
        if (task == GCD) return "gcd";
        return "?";
    }

    /// @notice Input determinístico nº `k` para a tarefa, derivado da seed.
    function inputFor(uint256 task, bytes32 seed, uint256 k) internal pure returns (bytes memory) {
        bytes32 h = keccak256(abi.encode(seed, k));
        if (task == FIB) return _le64(uint64(uint8(h[0]))); // n em [0, 255]
        if (task == POPCOUNT) return _le64(uint64(uint256(h)));
        if (task == ISQRT) {
            // alterna valores grandes e pequenos para cobrir os dois regimes
            uint64 x = uint64(uint256(h));
            if (k % 2 == 1) x >>= 40;
            return _le64(x);
        }
        if (task == MAX8) {
            bytes memory out;
            for (uint256 i = 0; i < 8; i++) {
                out = bytes.concat(out, _le64(uint64(uint256(keccak256(abi.encode(h, i))))));
            }
            return out;
        }
        if (task == GCD) {
            uint64 a = uint64(uint256(h));
            uint64 b = uint64(uint256(h) >> 64);
            // a cada 4 inputs um deles tem fator comum grande, para o mdc não ser quase sempre 1
            if (k % 4 == 3) {
                uint64 g = uint64(uint256(h) >> 128) | 1;
                a = uint64(uint256(a) * g);
                b = uint64(uint256(b) * g);
            }
            return bytes.concat(_le64(a), _le64(b));
        }
        revert("task");
    }

    /// @notice Resposta nativa. `input` tem o layout descrito nas constantes acima.
    function expected(uint256 task, bytes memory input) internal pure returns (uint64) {
        unchecked {
            if (task == FIB) {
                uint64 n = _u64(input, 0);
                uint64 a = 0;
                uint64 b = 1;
                for (uint64 i = 0; i < n; i++) {
                    (a, b) = (b, a + b); // wraparound em 64 bits
                }
                return a;
            }
            if (task == POPCOUNT) {
                uint64 x = _u64(input, 0);
                uint64 c = 0;
                while (x != 0) {
                    c += x & 1;
                    x >>= 1;
                }
                return c;
            }
            if (task == ISQRT) {
                uint256 x = _u64(input, 0);
                if (x == 0) return 0;
                uint256 r = x;
                uint256 y = (x + 1) / 2;
                while (y < r) {
                    r = y;
                    y = (y + x / y) / 2;
                }
                return uint64(r);
            }
            if (task == MAX8) {
                uint64 m = 0;
                for (uint256 i = 0; i < 8; i++) {
                    uint64 v = _u64(input, i * 8);
                    if (v > m) m = v;
                }
                return m;
            }
            if (task == GCD) {
                uint64 a = _u64(input, 0);
                uint64 b = _u64(input, 8);
                while (b != 0) {
                    (a, b) = (b, a % b);
                }
                return a;
            }
            revert("task");
        }
    }

    function _u64(bytes memory b, uint256 off) private pure returns (uint64 v) {
        for (uint256 i = 0; i < 8; i++) {
            v |= uint64(uint8(b[off + i])) << uint64(8 * i);
        }
    }

    function _le64(uint64 x) private pure returns (bytes memory) {
        x = ((x & 0x00000000ffffffff) << 32) | (x >> 32);
        x = ((x & 0x0000ffff0000ffff) << 16) | ((x >> 16) & 0x0000ffff0000ffff);
        x = ((x & 0x00ff00ff00ff00ff) << 8) | ((x >> 8) & 0x00ff00ff00ff00ff);
        return abi.encodePacked(bytes8(x));
    }
}

contracts/src/test/MockBlockHistory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

/// @dev Imita o contrato da EIP-2935 nos testes (o Hardhat 2.22 não tem Prague): instalado com
///      hardhat_setCode no endereço oficial. Calldata de 32 bytes = número do bloco.
contract MockBlockHistory {
    mapping(uint256 => bytes32) internal _hashes;

    function set(uint256 n, bytes32 h) external {
        _hashes[n] = h;
    }

    fallback(bytes calldata data) external returns (bytes memory) {
        require(data.length == 32);
        bytes32 h = _hashes[abi.decode(data, (uint256))];
        require(h != bytes32(0));
        return abi.encode(h);
    }
}
